18	     * 幂等记录视图。
19	     */
20	    public record IdempotentRecord(
21	            String requestId,
22	            String requestType,
23	            String fingerprint,
24	            int httpStatus,
25	            String responseBody,
26	            Long planId,
27	            LocalDateTime createdAt) {
