37	        var list = jdbc.query("""
38	                SELECT request_id, request_type, fingerprint, http_status, response_body, plan_id, created_at
39	                FROM idempotent_request WHERE request_id = ?
40	                """, (rs, n) -> new IdempotentRecord(
41	                rs.getString("request_id"),
42	                rs.getString("request_type"),
43	                rs.getString("fingerprint"),
44	                rs.getInt("http_status"),
45	                rs.getString("response_body"),
46	                (Long) rs.getObject("plan_id"),
47	                rs.getObject("created_at", LocalDateTime.class)), requestId);
48	        return list.isEmpty() ? null : list.get(0);
