public enum RejectCategory {
    /** 替代燃料热量替代率超过上限（恰40%合法）。 */
    RATE_EXCEEDED,
    /** 高氯硫燃料加权入窑氯总量超过限值。 */
    CHLORINE_EXCEEDED,
