        PlanResultResponse second = service.submit(TestFixtures.submit("REQ-EXE-2", KILN,
                VALID_LICENSE, "0.3000", DAY.atTime(0, 0), DAY.atTime(8, 0),
                List.of(TestFixtures.normalFuel())));
