package com.example.starter.api.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;

/**
 * 升温曲线阶段定义（合成曲线的一段）。
 *
 * @param targetTemp         目标温度，摄氏度，须为正数
 * @param maxDurationMinutes 最长用时，分钟，恰满未达目标自动转保温段
 */
public record WarmupStageSpec(
        @NotNull @DecimalMin(value = "0", inclusive = false) BigDecimal targetTemp,
        @NotNull @Min(1) Integer maxDurationMinutes) {
}

package com.example.starter.api.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

/**
 * 升温操作票创建请求（以 requestId 幂等）。创建即按合成曲线进入第一阶段。
 *
 * @param requestId    创建幂等键
 * @param kilnId       窑编号
 * @param curveVersion 合成升温曲线版本
 * @param stages       曲线阶段定义，至少一段，按顺序执行
 */
public record WarmupTicketCreateRequest(
        @NotBlank String requestId,
        @NotBlank String kilnId,
        @NotBlank String curveVersion,
        @NotEmpty @Valid List<WarmupStageSpec> stages) {
}

package com.example.starter.api.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 升温阶段确认请求（以 requestId 幂等）。阶段确认须两名不同操作人先后复核，
 * 单人确认不生效；确认时实测温度须达到阶段目标温度。
 *
 * @param requestId  确认幂等键
 * @param operatorId 操作人编号
 * @param actualTemp 实测温度，摄氏度，须大于等于阶段目标温度
 */
public record WarmupConfirmRequest(
        @NotBlank String requestId,
        @NotBlank String operatorId,
        @NotNull @DecimalMin(value = "0", inclusive = true) BigDecimal actualTemp) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 投料请求（以 requestId 幂等）。与升温曲线状态在同一事务内校验，曲线未走完禁止投料。
 *
 * @param requestId  投料幂等键
 * @param kilnId     窑编号
 * @param operatorId 操作人编号
 */
public record FeedRequest(
        @NotBlank String requestId,
        @NotBlank String kilnId,
        @NotBlank String operatorId) {
}

